import com.example.ticktok.R;
import com.example.ticktok.fragment.AddCategoryFragment;
import com.example.ticktok.fragment.CategoryFragment;
import com.example.ticktok.fragment.AddTaskBottomSheetFragment;
import com.example.ticktok.fragment.AddEventBottomSheetFragment;
import com.example.ticktok.adapter.MenuCategoryAdapter;
import com.example.ticktok.fragment.CalendarFragment;
import com.example.ticktok.fragment.EventFragment;
import com.example.ticktok.fragment.PomodoroFragment;
import com.example.ticktok.fragment.SearchFragment;
import com.example.ticktok.fragment.WelcomeFragment;
import com.example.ticktok.model.Category;
import com.example.ticktok.repository.CategoryRepository;
import com.example.ticktok.repository.CategoryRepositoryContract;
import com.example.ticktok.util.UserFirestorePaths;
import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;
import com.google.firebase.firestore.CollectionReference;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.Query;
import com.google.firebase.firestore.WriteBatch;

import java.util.ArrayList;
import java.util.Calendar;
import java.util.Date;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

public class MainActivity extends AppCompatActivity {

    private static final String STATE_SELECTED_MENU_TITLE = "state_selected_menu_title";
    private static final String TAG_ADD_TASK_SHEET = "add_task_sheet";
    private static final String TAG_ADD_EVENT_SHEET = "add_event_sheet";
    private static final String TAG_ADD_CATEGORY_SHEET = "add_category_sheet";

    private static final String PREFS_TASK_CLEANUP = "prefs_task_cleanup";
    private static final String PREF_KEY_LAST_CLEANUP_DAY_PREFIX = "last_cleanup_day_";

    private DrawerLayout drawerLayout;
    @Nullable
    private ImageButton btnMenu;
    private String selectedMenuTitle;
    private String selectedCategoryId;
    private CategoryRepositoryContract categoryRepository;
    private MenuCategoryAdapter categoryAdapter;
    private ItemTouchHelper categoryItemTouchHelper;
    private final List<Category> menuCategories = new ArrayList<>();
    private FloatingActionButton sharedFab;
    private boolean isPomodoroScreenActive;
    private boolean isSearchScreenActive;
    private ImageView dockIcon1;
    private ImageView dockIcon2;
    private ImageView dockIcon3;
    private ImageView dockIcon4;
    private ImageView dockIcon5;

    private boolean showingBackButton;

    private static final class ScreenState {
        final boolean isPomodoro;
        final boolean isSearch;
        final boolean isCalendar;
        final boolean isEvent;

        ScreenState(boolean isPomodoro, boolean isSearch, boolean isCalendar, boolean isEvent) {
            this.isPomodoro = isPomodoro;
            this.isSearch = isSearch;
            this.isCalendar = isCalendar;
            this.isEvent = isEvent;
        }
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);

        selectedMenuTitle = getString(R.string.menu_welcome);
        if (savedInstanceState != null) {
            String restored = savedInstanceState.getString(STATE_SELECTED_MENU_TITLE);
            if (restored != null && !restored.trim().isEmpty()) {
                selectedMenuTitle = restored;
            }
        }

        setupInsets();
        applySystemBars();
        applyScreenChrome(selectedMenuTitle);

        updateHeader(selectedMenuTitle);
        if (savedInstanceState == null) {
            showContentForMenu(selectedMenuTitle);
        }
        setupMenuButton();
        getSupportFragmentManager().addOnBackStackChangedListener(this::updateTopLeftNavigationButton);
        setupDrawerMenu();
        setupAddCategoryResultListener();
        setupSharedFab();
        setupDockNavigation();

        // Ensure the correct icon is set after initial fragment transaction.
        updateTopLeftNavigationButton();
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (FirebaseAuth.getInstance().getCurrentUser() == null) {
            Intent intent = new Intent(this, LoginActivity.class);
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
            startActivity(intent);
            finish();
            return;
        }

        // Delete tasks that were completed on previous days (run at most once per day).
        maybeRunDailyCompletedTaskCleanup();

        refreshCategories();
        syncFabVisibility();
    }

    private void maybeRunDailyCompletedTaskCleanup() {
        FirebaseUser user = FirebaseAuth.getInstance().getCurrentUser();
        if (user == null) {
            return;
        }

        String uid = user.getUid();
        String todayKey = getTodayKey();

        android.content.SharedPreferences prefs = getSharedPreferences(PREFS_TASK_CLEANUP, MODE_PRIVATE);
        String lastKey = prefs.getString(PREF_KEY_LAST_CLEANUP_DAY_PREFIX + uid, "");
        if (todayKey.equals(lastKey)) {
            return;
        }

        long todayStartMillis = normalizeToStartOfDay(System.currentTimeMillis());
        Date todayStartDate = new Date(todayStartMillis);

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            return;
        }

        Set<String> deletedIds = new HashSet<>();
        deleteCompletedTasksBefore(tasksRef, todayStartDate, deletedIds, () -> {
            // Extra safety: purge older completed tasks that might miss `completedAt`.
            purgeCompletedTasksWithoutTimestamp(tasksRef, "completed", todayStartDate, deletedIds, () ->
                    purgeCompletedTasksWithoutTimestamp(tasksRef, "isCompleted", todayStartDate, deletedIds, () ->
                            prefs.edit().putString(PREF_KEY_LAST_CLEANUP_DAY_PREFIX + uid, todayKey).apply()
                    )
            );
        });
    }

    @NonNull
    private String getTodayKey() {
        Calendar c = Calendar.getInstance();
        return String.format(Locale.US, "%04d%02d%02d",
                c.get(Calendar.YEAR),
                c.get(Calendar.MONTH) + 1,
                c.get(Calendar.DAY_OF_MONTH));
    }

    private long normalizeToStartOfDay(long millis) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTimeInMillis(millis);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        return calendar.getTimeInMillis();
    }

    private interface VoidCallback {
        void onDone();
    }

    private void deleteCompletedTasksBefore(@NonNull CollectionReference tasksRef,
                                           @NonNull Date todayStart,
                                           @NonNull Set<String> deletedIds,
                                           @NonNull VoidCallback onDone) {
        // Query only by `completedAt` to avoid composite indexes.
        Query q = tasksRef
                .whereLessThan("completedAt", todayStart)
                .orderBy("completedAt")
                .limit(450);

        q.get()
                .addOnSuccessListener(snapshot -> {
                    List<DocumentSnapshot> docs = snapshot.getDocuments();
                    if (docs.isEmpty()) {
                        onDone.onDone();
                        return;
                    }

                    WriteBatch batch = FirebaseFirestore.getInstance().batch();
                    for (DocumentSnapshot doc : docs) {
                        batch.delete(doc.getReference());
                        deletedIds.add(doc.getId());
                    }

                    batch.commit()
                            .addOnSuccessListener(unused -> deleteCompletedTasksBefore(tasksRef, todayStart, deletedIds, onDone))
                            .addOnFailureListener(error -> {
                                // If we fail (offline, permission, etc.), don't mark prefs.
                            });
                })
                .addOnFailureListener(error -> {
                    // Don't mark prefs on failure.
                });
    }

    private void purgeCompletedTasksWithoutTimestamp(@NonNull CollectionReference tasksRef,
                                                     @NonNull String completedField,
                                                     @NonNull Date todayStart,
                                                     @NonNull Set<String> deletedIds,
                                                     @NonNull VoidCallback onDone) {
        // Some older docs might have boolean completion set but missing completedAt.
        tasksRef.whereEqualTo(completedField, true)
                .limit(450)
                .get()
                .addOnSuccessListener(snapshot -> {
                    List<DocumentSnapshot> docs = snapshot.getDocuments();
                    if (docs.isEmpty()) {
                        onDone.onDone();
                        return;
                    }

                    List<DocumentSnapshot> toDelete = new ArrayList<>();
                    for (DocumentSnapshot doc : docs) {
                        if (deletedIds.contains(doc.getId())) {
                            continue;
                        }
                        Date completedAt = doc.getDate("completedAt");
                        if (completedAt == null || completedAt.before(todayStart)) {
                            toDelete.add(doc);
                        }
                    }

                    if (toDelete.isEmpty()) {
                        // Nothing to delete in this batch; assume remaining are today-completed.
                        onDone.onDone();
                        return;
                    }

                    WriteBatch batch = FirebaseFirestore.getInstance().batch();
                    for (DocumentSnapshot doc : toDelete) {
                        batch.delete(doc.getReference());
                        deletedIds.add(doc.getId());
                    }

                    batch.commit()
                            .addOnSuccessListener(unused -> purgeCompletedTasksWithoutTimestamp(tasksRef, completedField, todayStart, deletedIds, onDone))
                            .addOnFailureListener(error -> {
                                // Don't mark prefs on failure.
                            });
                })
                .addOnFailureListener(error -> {
                    // Don't mark prefs on failure.
                });
    }

    @Override
    protected void onSaveInstanceState(@NonNull Bundle outState) {
        super.onSaveInstanceState(outState);
        outState.putString(STATE_SELECTED_MENU_TITLE, selectedMenuTitle);
    }

    private void setupInsets() {
        drawerLayout = findViewById(R.id.main);
        if (drawerLayout == null) {
            return;
        }

        ViewCompat.setOnApplyWindowInsetsListener(drawerLayout, (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(0, 0, 0, systemBars.bottom);
            return insets;
        });
    }

    private void applySystemBars() {
        getWindow().setStatusBarColor(android.graphics.Color.BLACK);
        getWindow().setNavigationBarColor(android.graphics.Color.BLACK);

        WindowInsetsControllerCompat controller = WindowCompat.getInsetsController(getWindow(), getWindow().getDecorView());
        controller.setAppearanceLightStatusBars(false);
        controller.setAppearanceLightNavigationBars(false);
    }

    private void setupMenuButton() {
        btnMenu = findViewById(R.id.btnMenu);
        if (btnMenu == null) {
            return;
        }

        btnMenu.setOnClickListener(v -> {
            if (shouldShowBackButton()) {
                getOnBackPressedDispatcher().onBackPressed();
            } else {
                openDrawerMenu();
            }
        });

        updateTopLeftNavigationButton();
    }

    private boolean shouldShowBackButton() {
        return getSupportFragmentManager().getBackStackEntryCount() > 0;
    }

    private void updateTopLeftNavigationButton() {
        if (btnMenu == null) {
            return;
        }

        boolean showBack = shouldShowBackButton();
        if (showBack == showingBackButton) {
            return;
        }
        showingBackButton = showBack;

        btnMenu.setImageResource(showBack ? R.drawable.home_ic_back : R.drawable.home_ic_menu_more);
        btnMenu.setContentDescription(getString(showBack ? R.string.back_button : R.string.menu_button));
    }

    private void setupDrawerMenu() {
        categoryRepository = new CategoryRepository();

        setupProfileHeader();

        RecyclerView rvMenuCategories = findViewById(R.id.rvMenuCategories);
        if (rvMenuCategories != null) {
            rvMenuCategories.setLayoutManager(new LinearLayoutManager(this));
            categoryAdapter = new MenuCategoryAdapter(
                    this::onCategorySelected,
                    this::onCategoryLongPressed,
                    viewHolder -> {
                        if (categoryItemTouchHelper != null) {
                            categoryItemTouchHelper.startDrag(viewHolder);
                        }
                    }
            );
            rvMenuCategories.setAdapter(categoryAdapter);

            ItemTouchHelper.SimpleCallback callback = new ItemTouchHelper.SimpleCallback(
                    ItemTouchHelper.UP | ItemTouchHelper.DOWN,
                    0
            ) {
                @Override
                public boolean onMove(@NonNull RecyclerView recyclerView,
                                      @NonNull RecyclerView.ViewHolder viewHolder,
                                      @NonNull RecyclerView.ViewHolder target) {
                    if (categoryAdapter == null) {
                        return false;
                    }
                    int from = viewHolder.getBindingAdapterPosition();
                    int to = target.getBindingAdapterPosition();

                    // Position 0 is reserved for the fixed Welcome category.
                    if (from == 0 || to == 0) {
                        return false;
                    }
                    categoryAdapter.moveItem(from, to);
                    return true;
                }

                @Override
                public void onSwiped(@NonNull RecyclerView.ViewHolder viewHolder, int direction) {
                    // no-op (we don't support swipe)
                }

                @Override
                public void clearView(@NonNull RecyclerView recyclerView, @NonNull RecyclerView.ViewHolder viewHolder) {
                    super.clearView(recyclerView, viewHolder);
                    persistMenuCategoryOrder();
                }

                @Override
                public boolean isLongPressDragEnabled() {
                    // Drag is started via the handle to avoid conflict with long-press edit/delete.
                    return false;
                }
            };

            categoryItemTouchHelper = new ItemTouchHelper(callback);
            categoryItemTouchHelper.attachToRecyclerView(rvMenuCategories);
        }

        LinearLayout btnAdd = findViewById(R.id.btnAdd);
        if (btnAdd != null) {
            btnAdd.setOnClickListener(v -> openAddCategoryScreen());
        }

        refreshCategories();
    }

    private void persistMenuCategoryOrder() {
        if (categoryRepository == null || categoryAdapter == null) {
            return;
        }
        List<Category> items = categoryAdapter.getCurrentItems();
        if (items.isEmpty()) {
            return;
        }

        // Skip the fixed Welcome category (virtual, not stored in Firestore).
        List<Category> mutable = new ArrayList<>();
        for (Category c : items) {
            if (c != null && !Category.ID_WELCOME.equals(c.getId())) {
                mutable.add(c);
            }
        }
        if (mutable.isEmpty()) {
            return;
        }

        for (int i = 0; i < mutable.size(); i++) {
            mutable.get(i).setOrder(i + 1);
        }

        categoryRepository.updateCategoryOrders(mutable, new CategoryRepositoryContract.OnCategorySavedListener() {
            @Override
            public void onSuccess() {
                // Keep local cache consistent and refresh to ensure ordering is applied.
                menuCategories.clear();
                menuCategories.addAll(mutable);
                refreshCategories();
            }

            @Override
            public void onError(Exception e) {
                Toast.makeText(MainActivity.this, R.string.error_save_category_order, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void setupProfileHeader() {
        LinearLayout layoutUserProfile = findViewById(R.id.layoutUserProfile);
        TextView tvUserName = findViewById(R.id.tvUserName);

        FirebaseUser user = FirebaseAuth.getInstance().getCurrentUser();
        if (tvUserName != null) {
            tvUserName.setText(resolveDisplayName(user));
        }

        if (layoutUserProfile != null) {
            layoutUserProfile.setOnClickListener(v -> {
                Intent intent = new Intent(MainActivity.this, SettingsActivity.class);
                startActivity(intent);
                if (drawerLayout != null) {
                    drawerLayout.closeDrawer(GravityCompat.START);
                }
            });
        }
    }

    @NonNull
    private String resolveDisplayName(@Nullable FirebaseUser user) {
        if (user == null) {
            return getString(R.string.menu_user_default_name);
        }

        if (user.getDisplayName() != null && !user.getDisplayName().trim().isEmpty()) {
            return user.getDisplayName().trim();
        }

        if (user.getEmail() != null && !user.getEmail().trim().isEmpty()) {
            return user.getEmail().trim();
        }

        return getString(R.string.menu_user_default_name);
    }

    private void setupDockNavigation() {
        dockIcon1 = findViewById(R.id.dockIcon1);
        if (dockIcon1 != null) {
            dockIcon1.setOnClickListener(v -> openPomodoroScreen());
        }

        dockIcon3 = findViewById(R.id.dockIcon3);
        if (dockIcon3 != null) {
            dockIcon3.setOnClickListener(v -> openHomeScreen());
        }

        dockIcon2 = findViewById(R.id.dockIcon2);
        if (dockIcon2 != null) {
            dockIcon2.setOnClickListener(v -> openSearchScreen());
        }

        dockIcon4 = findViewById(R.id.dockIcon4);
        if (dockIcon4 != null) {
            dockIcon4.setOnClickListener(v -> openCalendarScreen());
        }

        dockIcon5 = findViewById(R.id.dockIcon5);
        if (dockIcon5 != null) {
            dockIcon5.setOnClickListener(v -> openEventScreen());
        }

        updateDockSelection(selectedMenuTitle);
    }

    private void setupSharedFab() {
        sharedFab = findViewById(R.id.fab);
        if (sharedFab == null) {
            return;
        }
        sharedFab.setOnClickListener(v -> openAddSheetForCurrentScreen());
        syncFabVisibility();
    }

    private void openAddSheetForCurrentScreen() {
        ScreenState state = evaluateScreenState(normalizeTitle(selectedMenuTitle));
        if (state.isEvent) {
            openAddEventBottomSheet();
            return;
        }
        openAddTaskBottomSheet();
    }

    private void syncFabVisibility() {
        updateFabVisibility(isAddCategorySheetShowing() || isPomodoroScreenActive || isSearchScreenActive);
    }

    private void updateFabVisibility(boolean hideFab) {
        if (sharedFab == null) {
            return;
        }
        sharedFab.setVisibility(hideFab ? View.GONE : View.VISIBLE);
    }

    private void openAddTaskBottomSheet() {
        if (getSupportFragmentManager().findFragmentByTag(TAG_ADD_TASK_SHEET) != null) {
            return;
        }

        Long prefillDueDate = null;
        Fragment currentFragment = getSupportFragmentManager().findFragmentById(R.id.contentFragmentContainer);
        if (currentFragment instanceof CalendarFragment) {
            prefillDueDate = ((CalendarFragment) currentFragment).getSelectedDateMillisForTask();
        }

        AddTaskBottomSheetFragment sheet = new AddTaskBottomSheetFragment(selectedCategoryId, prefillDueDate);
        sheet.show(getSupportFragmentManager(), TAG_ADD_TASK_SHEET);
    }

    private void openAddEventBottomSheet() {
        Fragment currentFragment = getSupportFragmentManager().findFragmentById(R.id.contentFragmentContainer);
        if (!(currentFragment instanceof EventFragment)) {
            return;
        }
        if (getSupportFragmentManager().findFragmentByTag(TAG_ADD_EVENT_SHEET) != null) {
            return;
        }
        AddEventBottomSheetFragment sheet = new AddEventBottomSheetFragment();
        sheet.show(getSupportFragmentManager(), TAG_ADD_EVENT_SHEET);
    }

    private void refreshCategories() {
        if (categoryRepository == null || categoryAdapter == null) {
            return;
        }

        categoryRepository.getCategories(new CategoryRepositoryContract.LoadCategoriesCallback() {
            @Override
            public void onLoaded(List<Category> categories) {
                menuCategories.clear();
                menuCategories.addAll(categories);

                // Keep selectedCategoryId stable if we are currently on a category screen.
                if (selectedCategoryId == null || selectedCategoryId.trim().isEmpty()) {
                    selectedCategoryId = resolveCategoryIdForTitle(normalizeTitle(selectedMenuTitle));
                }

                // Always show Welcome as the first (fixed) item.
                List<Category> display = new ArrayList<>();
                display.add(createWelcomeDrawerCategory());
                display.addAll(menuCategories);

                String highlightId = selectedCategoryId;
                if ((highlightId == null || highlightId.trim().isEmpty())
                        && getString(R.string.menu_welcome).equalsIgnoreCase(normalizeTitle(selectedMenuTitle))) {
                    highlightId = Category.ID_WELCOME;
                }

                categoryAdapter.submitList(display, selectedMenuTitle, highlightId);
            }

            @Override
            public void onError(Exception exception) {
                Toast.makeText(MainActivity.this, R.string.error_load_categories, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void setupAddCategoryResultListener() {
        getSupportFragmentManager().setFragmentResultListener(
                AddCategoryFragment.RESULT_KEY_ADD_CATEGORY,
                this,
                (requestKey, result) -> {
                    String updatedCategoryId = result.getString(AddCategoryFragment.RESULT_KEY_CATEGORY_ID);
                    String updatedName = result.getString(AddCategoryFragment.RESULT_KEY_CATEGORY_NAME);
                    if (updatedCategoryId != null
                            && updatedCategoryId.equals(selectedCategoryId)
                            && updatedName != null
                            && !updatedName.trim().isEmpty()) {
                        selectedMenuTitle = updatedName.trim();
                        updateHeader(selectedMenuTitle);
                    }
                    refreshCategories();
                }
        );
    }

    private void onCategorySelected(Category category) {
        if (category == null) {
            return;
        }

        // If the user navigates via the drawer while a Welcome filter is open, clear that back stack
        // so the top-left button returns to the menu icon and back won't jump to a stale filter.
        clearContentBackStackIfNeeded();

        if (Category.ID_WELCOME.equals(category.getId())) {
            selectedCategoryId = null;
            navigateTo(getString(R.string.menu_welcome), true, true);
            return;
        }

        // Navigate by ID to avoid title collisions (e.g., a user category named "Welcome").
        selectedCategoryId = category.getId();
        selectedMenuTitle = normalizeTitle(category.getTitle());
        updateHeader(selectedMenuTitle);
        applyScreenChrome(selectedMenuTitle);
        updateDockSelection(selectedMenuTitle);
        showCategoryScreen(selectedMenuTitle, selectedCategoryId);

        if (drawerLayout != null) {
            drawerLayout.closeDrawer(GravityCompat.START);
        }
        refreshCategories();
    }

    private void onCategoryLongPressed(@NonNull View anchorView, @NonNull Category category) {
        if (Category.ID_WELCOME.equals(category.getId())) {
            return;
        }
        showCategoryActionsPopup(anchorView, category);
    }

    @NonNull
    private Category createWelcomeDrawerCategory() {
        // Virtual category: not stored in Firestore.
        return new Category(Category.ID_WELCOME, "", getString(R.string.menu_welcome), 0);
    }

    private void showCategoryScreen(@NonNull String title, @Nullable String categoryId) {
        Fragment fragment = CategoryFragment.newInstance(title, categoryId);
        getSupportFragmentManager()
                .beginTransaction()
                .replace(R.id.contentFragmentContainer, fragment)
                .commit();
    }

    private void showCategoryActionsPopup(@NonNull View anchorView, @NonNull Category category) {
        PopupMenu popupMenu = new PopupMenu(this, anchorView);
        popupMenu.getMenuInflater().inflate(R.menu.menu_category_actions, popupMenu.getMenu());
        popupMenu.setOnMenuItemClickListener(item -> handleCategoryAction(item, category));
        popupMenu.show();
    }

    private boolean handleCategoryAction(@NonNull MenuItem item, @NonNull Category category) {
        int id = item.getItemId();
        if (id == R.id.action_category_edit) {
            openEditCategoryScreen(category);
            return true;
        }
        if (id == R.id.action_category_delete) {
            confirmDeleteCategory(category);
            return true;
        }
        return false;
    }

    private void openEditCategoryScreen(@NonNull Category category) {
        if (isAddCategorySheetShowing()) {
            return;
        }
        updateFabVisibility(true);
        AddCategoryFragment sheet = AddCategoryFragment.newInstanceForEdit(
                category.getId(),
                category.getTitle(),
                category.getIcon()
        );
        sheet.show(getSupportFragmentManager(), TAG_ADD_CATEGORY_SHEET);
    }

    private void confirmDeleteCategory(@NonNull Category category) {
        new AlertDialog.Builder(this)
                .setTitle(R.string.delete_category_title)
                .setMessage(getString(R.string.delete_category_message, category.getTitle()))
                .setNegativeButton(R.string.action_cancel, null)
                .setPositiveButton(R.string.action_delete, (dialog, which) -> deleteCategory(category))
                .show();
    }

    private void deleteCategory(@NonNull Category category) {
        if (categoryRepository == null) {
            categoryRepository = new CategoryRepository();
        }
        String categoryId = category.getId();
        if (categoryId == null || categoryId.trim().isEmpty()) {
            Toast.makeText(this, R.string.delete_category_failed, Toast.LENGTH_SHORT).show();
            return;
        }

        deleteTasksForCategory(categoryId, new FirestoreVoidCallback() {
            @Override
            public void onSuccess() {
                categoryRepository.deleteCategory(categoryId, new CategoryRepositoryContract.OnCategoryDeletedListener() {
                    @Override
                    public void onSuccess() {
                        Toast.makeText(MainActivity.this, R.string.delete_category_success, Toast.LENGTH_SHORT).show();
                        boolean wasSelected = categoryId.equals(selectedCategoryId);
                        if (wasSelected) {
                            selectedCategoryId = null;
                            navigateTo(getString(R.string.menu_welcome), true, true);
                        } else {
                            refreshCategories();
                        }
                    }

                    @Override
                    public void onError(Exception e) {
                        Toast.makeText(MainActivity.this, R.string.delete_category_failed, Toast.LENGTH_SHORT).show();
                    }
                });
            }

            @Override
            public void onError(@NonNull Exception e) {
                Toast.makeText(MainActivity.this, R.string.delete_category_failed, Toast.LENGTH_SHORT).show();
            }
        });
    }

    private interface FirestoreVoidCallback {
        void onSuccess();

        void onError(@NonNull Exception e);
    }

    private void deleteTasksForCategory(@NonNull String categoryId, @NonNull FirestoreVoidCallback callback) {
        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            callback.onSuccess();
            return;
        }

        tasksRef.whereEqualTo("categoryId", categoryId)
                .get()
                .addOnSuccessListener(snapshot -> {
                    List<DocumentSnapshot> documents = snapshot.getDocuments();
                    if (documents.isEmpty()) {
                        callback.onSuccess();
                        return;
                    }
                    deleteTasksInBatches(documents, 0, callback);
                })
                .addOnFailureListener(error -> callback.onError(asException(error)));
    }

    private void deleteTasksInBatches(@NonNull List<DocumentSnapshot> documents,
                                     int startIndex,
                                     @NonNull FirestoreVoidCallback callback) {
        if (startIndex >= documents.size()) {
            callback.onSuccess();
            return;
        }

        int endIndexExclusive = Math.min(startIndex + 450, documents.size());
        WriteBatch batch = FirebaseFirestore.getInstance().batch();
        for (int i = startIndex; i < endIndexExclusive; i++) {
            batch.delete(documents.get(i).getReference());
        }

        batch.commit()
                .addOnSuccessListener(unused -> deleteTasksInBatches(documents, endIndexExclusive, callback))
                .addOnFailureListener(error -> callback.onError(asException(error)));
    }

    @NonNull
    private Exception asException(@NonNull Exception e) {
        return e;
    }

    @NonNull
    private Exception asException(@NonNull Throwable throwable) {
        return throwable instanceof Exception ? (Exception) throwable : new Exception(throwable);
    }

    private void updateHeader(String title) {
        TextView headerText = findViewById(R.id.headerText);
        if (headerText == null) {
            return;
        }
        if (title == null || title.trim().isEmpty()) {
            headerText.setText(getString(R.string.menu_welcome));
            return;
        }
        headerText.setText(title);
    }

    private void showContentForMenu(String title) {
        String normalizedTitle = normalizeTitle(title);
        Fragment targetFragment = resolveFragmentForTitle(normalizedTitle);

        applyScreenChrome(normalizedTitle);
        updateDockSelection(normalizedTitle);

        getSupportFragmentManager()
                .beginTransaction()
                .replace(R.id.contentFragmentContainer, targetFragment)
                .commit();
    }

    private void applyScreenChrome(String title) {
        applyScreenChrome(evaluateScreenState(normalizeTitle(title)));
    }

    private void applyScreenChrome(ScreenState state) {
        isPomodoroScreenActive = state.isPomodoro;
        isSearchScreenActive = state.isSearch;

        View topBar = findViewById(R.id.topBar);
        TextView headerText = findViewById(R.id.headerText);

        if (topBar != null) {
            topBar.setVisibility((state.isPomodoro || state.isSearch || state.isCalendar || state.isEvent) ? View.GONE : View.VISIBLE);
        }
        if (headerText != null) {
            headerText.setVisibility((state.isPomodoro || state.isCalendar) ? View.GONE : View.VISIBLE);
        }

        if (drawerLayout != null) {
            drawerLayout.setDrawerLockMode((state.isPomodoro || state.isCalendar || state.isEvent)
                    ? DrawerLayout.LOCK_MODE_LOCKED_CLOSED
                    : DrawerLayout.LOCK_MODE_UNLOCKED);
            if (state.isPomodoro || state.isCalendar || state.isEvent) {
                drawerLayout.closeDrawer(GravityCompat.START);
            }
        }

        updateContentTopConstraint(state.isPomodoro || state.isCalendar);

        syncFabVisibility();
    }

    private void updateContentTopConstraint(boolean isPomodoro) {
        ConstraintLayout contentLayout = findViewById(R.id.contentLayout);
        if (contentLayout == null) {
            return;
        }

        ConstraintSet set = new ConstraintSet();
        set.clone(contentLayout);

        set.clear(R.id.contentFragmentContainer, ConstraintSet.TOP);
        if (isPomodoro) {
            set.connect(R.id.contentFragmentContainer, ConstraintSet.TOP, ConstraintSet.PARENT_ID, ConstraintSet.TOP, 0);
        } else {
            set.connect(R.id.contentFragmentContainer, ConstraintSet.TOP, R.id.headerText, ConstraintSet.BOTTOM, dpToPx(12));
        }
        set.applyTo(contentLayout);
    }

    private int dpToPx(int dp) {
        return Math.round(dp * getResources().getDisplayMetrics().density);
    }

    private void updateDockSelection(String title) {
        ScreenState state = evaluateScreenState(normalizeTitle(title));
        int unselectedColor = ContextCompat.getColor(this, R.color.text_white);
        int selectedColor = ContextCompat.getColor(this, R.color.fab_orange);

        setDockIconState(dockIcon1, false, unselectedColor);
        setDockIconState(dockIcon2, false, unselectedColor);
        setDockIconState(dockIcon3, false, unselectedColor);
        setDockIconState(dockIcon4, false, unselectedColor);
        setDockIconState(dockIcon5, false, unselectedColor);

        if (state.isPomodoro) {
            setDockIconState(dockIcon1, true, selectedColor);
        } else if (state.isSearch) {
            setDockIconState(dockIcon2, true, selectedColor);
        } else if (state.isCalendar) {
            setDockIconState(dockIcon4, true, selectedColor);
        } else if (state.isEvent) {
            setDockIconState(dockIcon5, true, selectedColor);
        } else {
            setDockIconState(dockIcon3, true, selectedColor);
        }
    }

    private void navigateTo(String title, boolean closeDrawer, boolean refreshCategoryList) {
        clearContentBackStackIfNeeded();
        selectedMenuTitle = normalizeTitle(title);
        selectedCategoryId = resolveCategoryIdForTitle(selectedMenuTitle);
        updateHeader(selectedMenuTitle);
        showContentForMenu(selectedMenuTitle);
        if (closeDrawer && drawerLayout != null) {
            drawerLayout.closeDrawer(GravityCompat.START);
        }
        if (refreshCategoryList) {
            refreshCategories();
        }
    }

    private void clearContentBackStackIfNeeded() {
        FragmentManager fm = getSupportFragmentManager();
        if (fm.isStateSaved()) {
            return;
        }
        if (fm.getBackStackEntryCount() > 0) {
            fm.popBackStackImmediate(null, FragmentManager.POP_BACK_STACK_INCLUSIVE);
        }
    }

    private String normalizeTitle(String title) {
        if (title == null || title.trim().isEmpty()) {
            return getString(R.string.menu_welcome);
        }
        return title.trim();
    }

    private ScreenState evaluateScreenState(String normalizedTitle) {
        return new ScreenState(
                getString(R.string.menu_pomodoro).equalsIgnoreCase(normalizedTitle),
                getString(R.string.menu_search).equalsIgnoreCase(normalizedTitle),
                getString(R.string.menu_calendar).equalsIgnoreCase(normalizedTitle),
                getString(R.string.menu_event).equalsIgnoreCase(normalizedTitle)
        );
    }

    private Fragment resolveFragmentForTitle(String normalizedTitle) {
        ScreenState state = evaluateScreenState(normalizedTitle);
        if (getString(R.string.menu_welcome).equalsIgnoreCase(normalizedTitle)) {
            return new WelcomeFragment();
        }
        if (state.isSearch) {
            return new SearchFragment();
        }
        if (state.isPomodoro) {
            return new PomodoroFragment();
        }
        if (state.isCalendar) {
            return new CalendarFragment();
        }
        if (state.isEvent) {
            return new EventFragment();
        }
        return CategoryFragment.newInstance(normalizedTitle, resolveCategoryIdForTitle(normalizedTitle));
    }

    @Nullable
    private String resolveCategoryIdForTitle(String normalizedTitle) {
        ScreenState state = evaluateScreenState(normalizedTitle);
        if (getString(R.string.menu_welcome).equalsIgnoreCase(normalizedTitle)
                || state.isSearch
                || state.isPomodoro
                || state.isCalendar
                || state.isEvent) {
            return null;
        }
        for (Category category : menuCategories) {
            if (category.getTitle() != null && category.getTitle().trim().equalsIgnoreCase(normalizedTitle)) {
                return category.getId();
            }
        }
        return null;
    }

    private void setDockIconState(ImageView icon, boolean isSelected, int color) {
        if (icon == null) {
            return;
        }
        icon.setColorFilter(color);
        float targetScale = isSelected ? 1.18f : 1f;
        float targetAlpha = isSelected ? 1f : 0.6f;
        icon.animate()
                .scaleX(targetScale)
                .scaleY(targetScale)
                .alpha(targetAlpha)
                .setDuration(160L)
                .start();
    }

    private void openAddCategoryScreen() {
        if (isAddCategorySheetShowing()) {
            return;
        }
        updateFabVisibility(true);

        AddCategoryFragment sheet = new AddCategoryFragment();
        sheet.show(getSupportFragmentManager(), TAG_ADD_CATEGORY_SHEET);
    }

    public void onAddCategorySheetDismissed() {
        syncFabVisibility();
        View root = findViewById(android.R.id.content);
        if (root != null) {
            root.post(this::syncFabVisibility);
        }
    }

    private boolean isAddCategorySheetShowing() {
        Fragment fragment = getSupportFragmentManager().findFragmentByTag(TAG_ADD_CATEGORY_SHEET);
        if (fragment instanceof DialogFragment) {
            android.app.Dialog dialog = ((DialogFragment) fragment).getDialog();
            return dialog != null && dialog.isShowing();
        }
        return fragment != null && fragment.isVisible();
    }

    private void openPomodoroScreen() {
        navigateTo(getString(R.string.menu_pomodoro), true, false);
    }

    private void openHomeScreen() {
        navigateTo(getString(R.string.menu_welcome), true, false);
    }

    private void openSearchScreen() {
        navigateTo(getString(R.string.menu_search), true, false);
    }

    private void openCalendarScreen() {
        navigateTo(getString(R.string.menu_calendar), true, false);
    }

    private void openEventScreen() {
        navigateTo(getString(R.string.menu_event), true, false);
    }


    private void openDrawerMenu() {
        if (drawerLayout != null) {
            drawerLayout.openDrawer(GravityCompat.START);
        }
    }

    /**
     * Allows child fragments (e.g., Welcome dashboard filters) to update the header title and chrome
     * without having to go through the drawer menu selection logic.
     */
    public void setScreenTitle(@NonNull String title) {
        selectedMenuTitle = normalizeTitle(title);
        // Filters are not tied to a single category.
        selectedCategoryId = null;
        updateHeader(selectedMenuTitle);
        applyScreenChrome(selectedMenuTitle);
        updateDockSelection(selectedMenuTitle);
    }

    /**
     * Opens a fragment on top of the current stack and updates the header title accordingly.
     * This is used by Welcome dashboard cards.
     */
    public void openFragmentWithTitle(@NonNull Fragment fragment, @NonNull String title) {
        setScreenTitle(title);
        getSupportFragmentManager()
                .beginTransaction()
                .replace(R.id.contentFragmentContainer, fragment)
                .addToBackStack(null)
                .commit();
    }
}

package com.example.ticktok.fragment;

import android.app.Dialog;
import android.content.Context;
import android.os.Bundle;
import android.view.Gravity;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.view.WindowManager;
import android.view.inputmethod.InputMethodManager;
import android.widget.ArrayAdapter;
import android.widget.EditText;
import android.widget.FrameLayout;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.ListAdapter;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.appcompat.widget.ListPopupWindow;
import androidx.core.content.ContextCompat;

import com.example.ticktok.R;
import com.example.ticktok.model.Task;
import com.example.ticktok.util.UserFirestorePaths;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.CollectionReference;
import com.google.android.material.bottomsheet.BottomSheetBehavior;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import com.google.android.material.bottomsheet.BottomSheetDialogFragment;

public class AddTaskBottomSheetFragment extends BottomSheetDialogFragment {
    private static final String ARG_CATEGORY_ID = "arg_category_id";
    private static final String ARG_PREFILL_DUE_DATE = "arg_prefill_due_date";
    private static final String ARG_MODE = "arg_mode";
    private static final String ARG_TASK_ID = "arg_task_id";
    private static final String ARG_TASK_TITLE = "arg_task_title";
    private static final String ARG_TASK_DESCRIPTION = "arg_task_description";
    private static final String ARG_TASK_PRIORITY = "arg_task_priority";
    private static final String ARG_TASK_DUE_DATE = "arg_task_due_date";

    private static final int MODE_ADD = 0;
    private static final int MODE_EDIT = 1;
    private static final int PRIORITY_NONE = 0;
    private static final int PRIORITY_LOW = 1;
    private static final int PRIORITY_MEDIUM = 2;
    private static final int PRIORITY_HIGH = 3;

    private long selectedDueDate = 0;
    private int selectedPriority = PRIORITY_NONE;
    private EditText taskInput;
    private ImageButton btnFlag;
    private String categoryId;

    private boolean isEditMode;
    @Nullable
    private String editingTaskId;
    @Nullable
    private String prefillTitle;
    @Nullable
    private String prefillDescription;

    public AddTaskBottomSheetFragment() {
    }

    public AddTaskBottomSheetFragment(@Nullable String categoryId) {
        Bundle args = new Bundle();
        args.putString(ARG_CATEGORY_ID, categoryId);
        setArguments(args);
    }

    public AddTaskBottomSheetFragment(@Nullable String categoryId, @Nullable Long prefillDueDate) {
        Bundle args = new Bundle();
        args.putString(ARG_CATEGORY_ID, categoryId);
        if (prefillDueDate != null && prefillDueDate > 0) {
            args.putLong(ARG_PREFILL_DUE_DATE, prefillDueDate);
        }
        setArguments(args);
    }

    @NonNull
    public static AddTaskBottomSheetFragment newInstanceForEdit(@NonNull Task task) {
        AddTaskBottomSheetFragment fragment = new AddTaskBottomSheetFragment();
        Bundle args = new Bundle();
        args.putInt(ARG_MODE, MODE_EDIT);
        args.putString(ARG_TASK_ID, task.getId());
        args.putString(ARG_CATEGORY_ID, task.getCategoryId());
        args.putString(ARG_TASK_TITLE, task.getTitle());
        args.putString(ARG_TASK_DESCRIPTION, task.getDescription());
        args.putInt(ARG_TASK_PRIORITY, task.getPriority());
        if (task.getDueDate() != null && task.getDueDate() > 0) {
            args.putLong(ARG_TASK_DUE_DATE, task.getDueDate());
        }
        fragment.setArguments(args);
        return fragment;
    }

    @Override
    public void onCreate(@Nullable Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        Bundle args = getArguments();
        if (args != null) {
            int mode = args.getInt(ARG_MODE, MODE_ADD);
            isEditMode = mode == MODE_EDIT;
            if (isEditMode) {
                editingTaskId = args.getString(ARG_TASK_ID);
                prefillTitle = args.getString(ARG_TASK_TITLE);
                prefillDescription = args.getString(ARG_TASK_DESCRIPTION);
                selectedPriority = args.getInt(ARG_TASK_PRIORITY, PRIORITY_NONE);
                if (args.containsKey(ARG_TASK_DUE_DATE)) {
                    selectedDueDate = normalizeToStartOfDay(args.getLong(ARG_TASK_DUE_DATE, 0L));
                }
            }

            categoryId = args.getString(ARG_CATEGORY_ID);
            if (args.containsKey(ARG_PREFILL_DUE_DATE)) {
                selectedDueDate = normalizeToStartOfDay(args.getLong(ARG_PREFILL_DUE_DATE, 0L));
            }
        }
    }

    @NonNull
    @Override
    public Dialog onCreateDialog(@Nullable Bundle savedInstanceState) {
        BottomSheetDialog dialog = (BottomSheetDialog) super.onCreateDialog(savedInstanceState);

        if (dialog.getWindow() != null) {
            dialog.getWindow().setSoftInputMode(
                    WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE
                            | WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE
            );
        }

        dialog.setOnShowListener(d -> {
            int bottomSheetId = getResources().getIdentifier("design_bottom_sheet", "id", "com.google.android.material");
            FrameLayout bottomSheet = dialog.findViewById(bottomSheetId);
            if (bottomSheet == null) {
                return;
            }

            bottomSheet.setBackgroundResource(android.R.color.transparent);
            BottomSheetBehavior<FrameLayout> behavior = BottomSheetBehavior.from(bottomSheet);
            behavior.setState(BottomSheetBehavior.STATE_EXPANDED);
            behavior.setSkipCollapsed(true);
        });

        return dialog;
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.bottom_sheet_add_task, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);
        taskInput = view.findViewById(R.id.etTaskInput);
        if (taskInput == null) {
            return;
        }

        ImageButton btnMicrophone = view.findViewById(R.id.btnMicrophone);
        ImageButton btnSend = view.findViewById(R.id.btnSend);
        if (btnSend != null) {
            btnSend.setOnClickListener(v -> handleSendTask());
        }
        ImageButton btnCalendar = view.findViewById(R.id.btnCalendar);
        if (btnCalendar != null) {
            btnCalendar.setOnClickListener(v -> showDatePicker());
            if (selectedDueDate > 0) {
                btnCalendar.setColorFilter(android.graphics.Color.parseColor("#FF9800"));
            }
        }
        btnFlag = view.findViewById(R.id.btnFlag);
        if (btnFlag != null) {
            btnFlag.setOnClickListener(v -> showPriorityMenu(v));
            applySelectedPriorityColor();
        }

        if (isEditMode) {
            String title = prefillTitle == null ? "" : prefillTitle.trim();
            String desc = prefillDescription == null ? "" : prefillDescription.trim();
            String combined;
            if (!desc.isEmpty()) {
                combined = title + "\n" + desc;
            } else {
                combined = title;
            }
            taskInput.setText(combined);
            taskInput.setSelection(taskInput.getText() != null ? taskInput.getText().length() : 0);
        }

        updateSendMicVisibility(btnMicrophone, btnSend, taskInput.getText());

        taskInput.addTextChangedListener(new android.text.TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                updateSendMicVisibility(btnMicrophone, btnSend, s);
            }

            @Override
            public void afterTextChanged(android.text.Editable s) {}
        });

        taskInput.requestFocus();
        taskInput.post(() -> {
            Context context = getContext();
            if (context == null) {
                return;
            }
            InputMethodManager imm = (InputMethodManager) context.getSystemService(Context.INPUT_METHOD_SERVICE);
            if (imm != null) {
                imm.showSoftInput(taskInput, InputMethodManager.SHOW_IMPLICIT);
            }
        });
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        taskInput = null;
        btnFlag = null;
    }

    private void showDatePicker() {
        final java.util.Calendar c = java.util.Calendar.getInstance();
        if (selectedDueDate > 0) {
            c.setTimeInMillis(selectedDueDate);
        }
        int year = c.get(java.util.Calendar.YEAR);
        int month = c.get(java.util.Calendar.MONTH);
        int day = c.get(java.util.Calendar.DAY_OF_MONTH);

        android.app.DatePickerDialog datePickerDialog = new android.app.DatePickerDialog(
                requireContext(),
                (view, year1, monthOfYear, dayOfMonth) -> {
                    java.util.Calendar selectedCalendar = java.util.Calendar.getInstance();
                    selectedCalendar.set(year1, monthOfYear, dayOfMonth);
                    selectedDueDate = normalizeToStartOfDay(selectedCalendar.getTimeInMillis());

                    View root = getView();
                    if (root != null) {
                        ImageButton btnCalendar = root.findViewById(R.id.btnCalendar);
                        if (btnCalendar != null) {
                            btnCalendar.setColorFilter(android.graphics.Color.parseColor("#FF9800"));
                        }
                    }
                },
                year, month, day
        );
        datePickerDialog.show();
    }

    private void showPriorityMenu(View anchor) {
        restoreTaskInputFocus();

        PriorityOption[] options = new PriorityOption[] {
                new PriorityOption(PRIORITY_HIGH, getString(R.string.priority_high), "#F44336"),
                new PriorityOption(PRIORITY_MEDIUM, getString(R.string.priority_medium), "#FFC107"),
                new PriorityOption(PRIORITY_LOW, getString(R.string.priority_low), "#2196F3"),
                new PriorityOption(PRIORITY_NONE, getString(R.string.priority_none), "#9E9E9E")
        };

        ListPopupWindow popupWindow = new ListPopupWindow(
                requireContext(),
                null,
                0,
                R.style.Widget_TickTok_PriorityListPopupWindow
        );
        popupWindow.setAnchorView(anchor);
        popupWindow.setModal(false);
        popupWindow.setInputMethodMode(ListPopupWindow.INPUT_METHOD_NOT_NEEDED);
        popupWindow.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_UNCHANGED);
        popupWindow.setContentWidth(dpToPx(196));
        popupWindow.setDropDownGravity(Gravity.START);
        popupWindow.setAdapter(createPriorityAdapter(options));
        popupWindow.setOnItemClickListener((parent, view, position, id) -> {
            selectedPriority = options[position].value;
            applySelectedPriorityColor();
            popupWindow.dismiss();
        });
        popupWindow.setOnDismissListener(this::restoreTaskInputFocus);
        popupWindow.show();
        restoreTaskInputFocus();
    }

    private ListAdapter createPriorityAdapter(PriorityOption[] options) {
        return new ArrayAdapter<PriorityOption>(requireContext(), 0, options) {
            @NonNull
            @Override
            public View getView(int position, @Nullable View convertView, @NonNull ViewGroup parent) {
                View itemView = convertView;
                if (itemView == null) {
                    itemView = LayoutInflater.from(getContext())
                            .inflate(R.layout.item_priority_option, parent, false);
                }
                PriorityOption option = getItem(position);
                if (option == null) {
                    return itemView;
                }

                ImageView icon = itemView.findViewById(R.id.ivPriorityIcon);
                TextView title = itemView.findViewById(R.id.tvPriorityTitle);
                if (icon != null) {
                    icon.setColorFilter(android.graphics.Color.parseColor(option.tintHex));
                }
                if (title != null) {
                    title.setText(option.title);
                }
                return itemView;
            }
        };
    }

    private void applySelectedPriorityColor() {
        if (btnFlag == null) {
            return;
        }
        btnFlag.setColorFilter(resolvePriorityColor(selectedPriority));
    }

    private void restoreTaskInputFocus() {
        if (taskInput == null) {
            return;
        }
        taskInput.requestFocus();

        Context context = getContext();
        if (context == null) {
            return;
        }

        InputMethodManager imm = (InputMethodManager) context.getSystemService(Context.INPUT_METHOD_SERVICE);
        if (imm != null) {
            imm.showSoftInput(taskInput, InputMethodManager.SHOW_IMPLICIT);
        }
    }

    private int dpToPx(int dp) {
        return Math.round(dp * requireContext().getResources().getDisplayMetrics().density);
    }

    private int resolvePriorityColor(int priority) {
        switch (priority) {
            case PRIORITY_HIGH:
                return android.graphics.Color.parseColor("#F44336");
            case PRIORITY_MEDIUM:
                return android.graphics.Color.parseColor("#FFC107");
            case PRIORITY_LOW:
                return android.graphics.Color.parseColor("#2196F3");
            case PRIORITY_NONE:
            default:
                return ContextCompat.getColor(requireContext(), R.color.text_white);
        }
    }

    private void handleSendTask() {
        if (taskInput == null) {
            return;
        }

        String rawInput = taskInput.getText() != null ? taskInput.getText().toString().trim() : "";
        if (rawInput.isEmpty()) {
            Toast.makeText(requireContext(), R.string.add_task_hint, Toast.LENGTH_SHORT).show();
            return;
        }

        String title = extractTitle(rawInput);
        String description = extractDescription(rawInput);
        Long dueDateValue = selectedDueDate > 0
                ? normalizeToStartOfDay(selectedDueDate)
                : getStartOfTodayMillis();

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            Toast.makeText(requireContext(), R.string.auth_error_login_required, Toast.LENGTH_SHORT).show();
            return;
        }

        if (isEditMode) {
            if (editingTaskId == null || editingTaskId.trim().isEmpty()) {
                Toast.makeText(requireContext(), R.string.delete_task_failed, Toast.LENGTH_SHORT).show();
                return;
            }

            java.util.Map<String, Object> updates = new java.util.HashMap<>();
            updates.put("title", title);
            updates.put("description", description);
            updates.put("priority", selectedPriority);
            updates.put("dueDate", dueDateValue);
            updates.put("categoryId", categoryId);

            tasksRef.document(editingTaskId.trim())
                    .update(updates)
                    .addOnSuccessListener(unused -> {
                        Toast.makeText(requireContext(), R.string.edit_task_success, Toast.LENGTH_SHORT).show();
                        dismiss();
                    })
                    .addOnFailureListener(e -> Toast.makeText(requireContext(), e.getMessage(), Toast.LENGTH_SHORT).show());
            return;
        }

        addNewTaskWithNextOrder(tasksRef, title, description, dueDateValue);
    }

    private void addNewTaskWithNextOrder(@NonNull CollectionReference tasksRef,
                                        @NonNull String title,
                                        @NonNull String description,
                                        @NonNull Long dueDateValue) {
        // Use a time-based order to avoid Firestore composite-index requirements.
        // (Drag & drop will later rewrite orders to 1..N anyway.)
        int nextOrder = (int) (System.currentTimeMillis() / 1000L);
        Task task = new Task(title, description, categoryId, selectedPriority, dueDateValue, nextOrder);
        task.setCompleted(false);
        task.setOrder(nextOrder);
        task.setCreatedAt(null);

        tasksRef
                .add(task)
                .addOnSuccessListener(documentReference -> {
                    documentReference.update("createdAt", FieldValue.serverTimestamp());
                    Toast.makeText(requireContext(), R.string.add_task_success, Toast.LENGTH_SHORT).show();
                    dismiss();
                })
                .addOnFailureListener(e -> Toast.makeText(requireContext(), e.getMessage(), Toast.LENGTH_SHORT).show());
    }

    private void updateSendMicVisibility(@Nullable ImageButton btnMicrophone,
                                        @Nullable ImageButton btnSend,
                                        @Nullable CharSequence text) {
        boolean hasText = text != null && !text.toString().trim().isEmpty();
        if (btnMicrophone != null) {
            btnMicrophone.setVisibility(hasText ? View.GONE : View.VISIBLE);
        }
        if (btnSend != null) {
            btnSend.setVisibility(hasText ? View.VISIBLE : View.GONE);
        }
    }

    private String extractTitle(String rawInput) {
        String[] lines = rawInput.split("\\n", 2);
        String firstLine = lines[0].trim();
        return firstLine.isEmpty() ? rawInput : firstLine;
    }

    private String extractDescription(String rawInput) {
        String[] lines = rawInput.split("\\n", 2);
        if (lines.length < 2) {
            return "";
        }
        return lines[1].trim();
    }

    private long normalizeToStartOfDay(long millis) {
        if (millis <= 0) {
            return 0L;
        }
        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.setTimeInMillis(millis);
        calendar.set(java.util.Calendar.HOUR_OF_DAY, 0);
        calendar.set(java.util.Calendar.MINUTE, 0);
        calendar.set(java.util.Calendar.SECOND, 0);
        calendar.set(java.util.Calendar.MILLISECOND, 0);
        return calendar.getTimeInMillis();
    }

    private long getStartOfTodayMillis() {
        return normalizeToStartOfDay(System.currentTimeMillis());
    }

    private static class PriorityOption {
        final int value;
        final String title;
        final String tintHex;

        PriorityOption(int value, String title, String tintHex) {
            this.value = value;
            this.title = title;
            this.tintHex = tintHex;
        }

        @NonNull
        @Override
        public String toString() {
            return title;
        }
    }
}

package com.example.ticktok.fragment;

import android.app.Dialog;
import android.content.Context;
import android.os.Bundle;
import android.view.Gravity;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.view.WindowManager;
import android.view.inputmethod.InputMethodManager;
import android.widget.ArrayAdapter;
import android.widget.EditText;
import android.widget.FrameLayout;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.ListAdapter;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.appcompat.widget.ListPopupWindow;
import androidx.core.content.ContextCompat;

import com.example.ticktok.R;
import com.example.ticktok.model.Task;
import com.example.ticktok.reminder.ReminderManager;
import com.example.ticktok.util.UserFirestorePaths;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.CollectionReference;
import com.google.android.material.bottomsheet.BottomSheetBehavior;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import com.google.android.material.bottomsheet.BottomSheetDialogFragment;

public class AddTaskBottomSheetFragment extends BottomSheetDialogFragment {
    private static final String ARG_CATEGORY_ID = "arg_category_id";
    private static final String ARG_PREFILL_DUE_DATE = "arg_prefill_due_date";
    private static final String ARG_MODE = "arg_mode";
    private static final String ARG_TASK_ID = "arg_task_id";
    private static final String ARG_TASK_TITLE = "arg_task_title";
    private static final String ARG_TASK_DESCRIPTION = "arg_task_description";
    private static final String ARG_TASK_PRIORITY = "arg_task_priority";
    private static final String ARG_TASK_DUE_DATE = "arg_task_due_date";
    private static final String ARG_TASK_REMINDER_TIME = "arg_task_reminder_time";

    private static final int MODE_ADD = 0;
    private static final int MODE_EDIT = 1;
    private static final int PRIORITY_NONE = 0;
    private static final int PRIORITY_LOW = 1;
    private static final int PRIORITY_MEDIUM = 2;
    private static final int PRIORITY_HIGH = 3;

    private long selectedDueDate = 0;
    private long selectedReminderTime = 0;
    private int selectedPriority = PRIORITY_NONE;
    private EditText taskInput;
    private ImageButton btnFlag;
    private String categoryId;

    private boolean isEditMode;
    @Nullable
    private String editingTaskId;
    @Nullable
    private String prefillTitle;
    @Nullable
    private String prefillDescription;

    private long originalReminderTime = 0L;

    public AddTaskBottomSheetFragment() {
    }

    public AddTaskBottomSheetFragment(@Nullable String categoryId) {
        Bundle args = new Bundle();
        args.putString(ARG_CATEGORY_ID, categoryId);
        setArguments(args);
    }

    public AddTaskBottomSheetFragment(@Nullable String categoryId, @Nullable Long prefillDueDate) {
        Bundle args = new Bundle();
        args.putString(ARG_CATEGORY_ID, categoryId);
        if (prefillDueDate != null && prefillDueDate > 0) {
            args.putLong(ARG_PREFILL_DUE_DATE, prefillDueDate);
        }
        setArguments(args);
    }

    @NonNull
    public static AddTaskBottomSheetFragment newInstanceForEdit(@NonNull Task task) {
        AddTaskBottomSheetFragment fragment = new AddTaskBottomSheetFragment();
        Bundle args = new Bundle();
        args.putInt(ARG_MODE, MODE_EDIT);
        args.putString(ARG_TASK_ID, task.getId());
        args.putString(ARG_CATEGORY_ID, task.getCategoryId());
        args.putString(ARG_TASK_TITLE, task.getTitle());
        args.putString(ARG_TASK_DESCRIPTION, task.getDescription());
        args.putInt(ARG_TASK_PRIORITY, task.getPriority());
        if (task.getDueDate() != null && task.getDueDate() > 0) {
            args.putLong(ARG_TASK_DUE_DATE, task.getDueDate());
        }
        if (task.getReminderTime() != null && task.getReminderTime() > 0) {
            args.putLong(ARG_TASK_REMINDER_TIME, task.getReminderTime());
        }
        fragment.setArguments(args);
        return fragment;
    }

    @Override
    public void onCreate(@Nullable Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        Bundle args = getArguments();
        if (args != null) {
            int mode = args.getInt(ARG_MODE, MODE_ADD);
            isEditMode = mode == MODE_EDIT;
            if (isEditMode) {
                editingTaskId = args.getString(ARG_TASK_ID);
                prefillTitle = args.getString(ARG_TASK_TITLE);
                prefillDescription = args.getString(ARG_TASK_DESCRIPTION);
                selectedPriority = args.getInt(ARG_TASK_PRIORITY, PRIORITY_NONE);
                if (args.containsKey(ARG_TASK_DUE_DATE)) {
                    selectedDueDate = normalizeToStartOfDay(args.getLong(ARG_TASK_DUE_DATE, 0L));
                }

                if (args.containsKey(ARG_TASK_REMINDER_TIME)) {
                    selectedReminderTime = args.getLong(ARG_TASK_REMINDER_TIME, 0L);
                    originalReminderTime = selectedReminderTime;
                }
            }

            categoryId = args.getString(ARG_CATEGORY_ID);
            if (args.containsKey(ARG_PREFILL_DUE_DATE)) {
                selectedDueDate = normalizeToStartOfDay(args.getLong(ARG_PREFILL_DUE_DATE, 0L));
            }
        }
    }

    @NonNull
    @Override
    public Dialog onCreateDialog(@Nullable Bundle savedInstanceState) {
        BottomSheetDialog dialog = (BottomSheetDialog) super.onCreateDialog(savedInstanceState);

        if (dialog.getWindow() != null) {
            dialog.getWindow().setSoftInputMode(
                    WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE
                            | WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE
            );
        }

        dialog.setOnShowListener(d -> {
            int bottomSheetId = getResources().getIdentifier("design_bottom_sheet", "id", "com.google.android.material");
            FrameLayout bottomSheet = dialog.findViewById(bottomSheetId);
            if (bottomSheet == null) {
                return;
            }

            bottomSheet.setBackgroundResource(android.R.color.transparent);
            BottomSheetBehavior<FrameLayout> behavior = BottomSheetBehavior.from(bottomSheet);
            behavior.setState(BottomSheetBehavior.STATE_EXPANDED);
            behavior.setSkipCollapsed(true);
        });

        return dialog;
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.bottom_sheet_add_task, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);
        taskInput = view.findViewById(R.id.etTaskInput);
        if (taskInput == null) {
            return;
        }

        ImageButton btnMicrophone = view.findViewById(R.id.btnMicrophone);
        ImageButton btnSend = view.findViewById(R.id.btnSend);
        if (btnSend != null) {
            btnSend.setOnClickListener(v -> handleSendTask());
        }
        ImageButton btnCalendar = view.findViewById(R.id.btnCalendar);
        if (btnCalendar != null) {
            btnCalendar.setOnClickListener(v -> showDatePicker());
            if (selectedDueDate > 0) {
                btnCalendar.setColorFilter(android.graphics.Color.parseColor("#FF9800"));
            }
        }
        btnFlag = view.findViewById(R.id.btnFlag);
        if (btnFlag != null) {
            btnFlag.setOnClickListener(v -> showPriorityMenu(v));
            applySelectedPriorityColor();
        }

        ImageButton btnMore = view.findViewById(R.id.btnMore);
        if (btnMore != null) {
            // Reminder: pick TIME only to avoid re-selecting the date (the date comes from dueDate).
            btnMore.setOnClickListener(v -> showReminderTimePicker());
            btnMore.setOnLongClickListener(v -> {
                selectedReminderTime = 0L;
                btnMore.setColorFilter(ContextCompat.getColor(requireContext(), R.color.text_white));
                Toast.makeText(requireContext(), R.string.reminder_cleared, Toast.LENGTH_SHORT).show();
                return true;
            });
            if (selectedReminderTime > 0) {
                btnMore.setColorFilter(android.graphics.Color.parseColor("#FF9800"));
            }
        }

        if (isEditMode) {
            String title = prefillTitle == null ? "" : prefillTitle.trim();
            String desc = prefillDescription == null ? "" : prefillDescription.trim();
            String combined;
            if (!desc.isEmpty()) {
                combined = title + "\n" + desc;
            } else {
                combined = title;
            }
            taskInput.setText(combined);
            taskInput.setSelection(taskInput.getText() != null ? taskInput.getText().length() : 0);
        }

        updateSendMicVisibility(btnMicrophone, btnSend, taskInput.getText());

        taskInput.addTextChangedListener(new android.text.TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                updateSendMicVisibility(btnMicrophone, btnSend, s);
            }

            @Override
            public void afterTextChanged(android.text.Editable s) {}
        });

        taskInput.requestFocus();
        taskInput.post(() -> {
            Context context = getContext();
            if (context == null) {
                return;
            }
            InputMethodManager imm = (InputMethodManager) context.getSystemService(Context.INPUT_METHOD_SERVICE);
            if (imm != null) {
                imm.showSoftInput(taskInput, InputMethodManager.SHOW_IMPLICIT);
            }
        });
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        taskInput = null;
        btnFlag = null;
    }

    private void showDatePicker() {
        final java.util.Calendar c = java.util.Calendar.getInstance();
        if (selectedDueDate > 0) {
            c.setTimeInMillis(selectedDueDate);
        }
        int year = c.get(java.util.Calendar.YEAR);
        int month = c.get(java.util.Calendar.MONTH);
        int day = c.get(java.util.Calendar.DAY_OF_MONTH);

        android.app.DatePickerDialog datePickerDialog = new android.app.DatePickerDialog(
                requireContext(),
                (view, year1, monthOfYear, dayOfMonth) -> {
                    java.util.Calendar selectedCalendar = java.util.Calendar.getInstance();
                    selectedCalendar.set(year1, monthOfYear, dayOfMonth);
                    selectedDueDate = normalizeToStartOfDay(selectedCalendar.getTimeInMillis());

                    // If a reminder time is already set, keep the same hour/minute but move it to the new date.
                    if (selectedReminderTime > 0) {
                        java.util.Calendar reminderCal = java.util.Calendar.getInstance();
                        reminderCal.setTimeInMillis(selectedReminderTime);
                        int hour = reminderCal.get(java.util.Calendar.HOUR_OF_DAY);
                        int minute = reminderCal.get(java.util.Calendar.MINUTE);

                        java.util.Calendar newReminder = java.util.Calendar.getInstance();
                        newReminder.setTimeInMillis(selectedDueDate);
                        newReminder.set(java.util.Calendar.HOUR_OF_DAY, hour);
                        newReminder.set(java.util.Calendar.MINUTE, minute);
                        newReminder.set(java.util.Calendar.SECOND, 0);
                        newReminder.set(java.util.Calendar.MILLISECOND, 0);
                        selectedReminderTime = newReminder.getTimeInMillis();
                    }

                    View root = getView();
                    if (root != null) {
                        ImageButton btnCalendar = root.findViewById(R.id.btnCalendar);
                        if (btnCalendar != null) {
                            btnCalendar.setColorFilter(android.graphics.Color.parseColor("#FF9800"));
                        }
                    }
                },
                year, month, day
        );
        datePickerDialog.show();
    }

    private void showPriorityMenu(View anchor) {
        restoreTaskInputFocus();

        PriorityOption[] options = new PriorityOption[] {
                new PriorityOption(PRIORITY_HIGH, getString(R.string.priority_high), "#F44336"),
                new PriorityOption(PRIORITY_MEDIUM, getString(R.string.priority_medium), "#FFC107"),
                new PriorityOption(PRIORITY_LOW, getString(R.string.priority_low), "#2196F3"),
                new PriorityOption(PRIORITY_NONE, getString(R.string.priority_none), "#9E9E9E")
        };

        ListPopupWindow popupWindow = new ListPopupWindow(
                requireContext(),
                null,
                0,
                R.style.Widget_TickTok_PriorityListPopupWindow
        );
        popupWindow.setAnchorView(anchor);
        popupWindow.setModal(false);
        popupWindow.setInputMethodMode(ListPopupWindow.INPUT_METHOD_NOT_NEEDED);
        popupWindow.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_UNCHANGED);
        popupWindow.setContentWidth(dpToPx(196));
        popupWindow.setDropDownGravity(Gravity.START);
        popupWindow.setAdapter(createPriorityAdapter(options));
        popupWindow.setOnItemClickListener((parent, view, position, id) -> {
            selectedPriority = options[position].value;
            applySelectedPriorityColor();
            popupWindow.dismiss();
        });
        popupWindow.setOnDismissListener(this::restoreTaskInputFocus);
        popupWindow.show();
        restoreTaskInputFocus();
    }

    private ListAdapter createPriorityAdapter(PriorityOption[] options) {
        return new ArrayAdapter<PriorityOption>(requireContext(), 0, options) {
            @NonNull
            @Override
            public View getView(int position, @Nullable View convertView, @NonNull ViewGroup parent) {
                View itemView = convertView;
                if (itemView == null) {
                    itemView = LayoutInflater.from(getContext())
                            .inflate(R.layout.item_priority_option, parent, false);
                }
                PriorityOption option = getItem(position);
                if (option == null) {
                    return itemView;
                }

                ImageView icon = itemView.findViewById(R.id.ivPriorityIcon);
                TextView title = itemView.findViewById(R.id.tvPriorityTitle);
                if (icon != null) {
                    icon.setColorFilter(android.graphics.Color.parseColor(option.tintHex));
                }
                if (title != null) {
                    title.setText(option.title);
                }
                return itemView;
            }
        };
    }

    private void applySelectedPriorityColor() {
        if (btnFlag == null) {
            return;
        }
        btnFlag.setColorFilter(resolvePriorityColor(selectedPriority));
    }

    private void restoreTaskInputFocus() {
        if (taskInput == null) {
            return;
        }
        taskInput.requestFocus();

        Context context = getContext();
        if (context == null) {
            return;
        }

        InputMethodManager imm = (InputMethodManager) context.getSystemService(Context.INPUT_METHOD_SERVICE);
        if (imm != null) {
            imm.showSoftInput(taskInput, InputMethodManager.SHOW_IMPLICIT);
        }
    }

    private int dpToPx(int dp) {
        return Math.round(dp * requireContext().getResources().getDisplayMetrics().density);
    }

    private int resolvePriorityColor(int priority) {
        switch (priority) {
            case PRIORITY_HIGH:
                return android.graphics.Color.parseColor("#F44336");
            case PRIORITY_MEDIUM:
                return android.graphics.Color.parseColor("#FFC107");
            case PRIORITY_LOW:
                return android.graphics.Color.parseColor("#2196F3");
            case PRIORITY_NONE:
            default:
                return ContextCompat.getColor(requireContext(), R.color.text_white);
        }
    }

    private void handleSendTask() {
        if (taskInput == null) {
            return;
        }

        String rawInput = taskInput.getText() != null ? taskInput.getText().toString().trim() : "";
        if (rawInput.isEmpty()) {
            Toast.makeText(requireContext(), R.string.add_task_hint, Toast.LENGTH_SHORT).show();
            return;
        }

        String title = extractTitle(rawInput);
        String description = extractDescription(rawInput);
        Long dueDateValue = selectedDueDate > 0
                ? normalizeToStartOfDay(selectedDueDate)
                : getStartOfTodayMillis();

        long reminderTimeValue = selectedReminderTime > 0 ? selectedReminderTime : 0L;
        if (reminderTimeValue > 0 && reminderTimeValue <= System.currentTimeMillis()) {
            // Don't persist a reminder that can't actually fire.
            reminderTimeValue = 0L;
            selectedReminderTime = 0L;
            View root = getView();
            if (root != null) {
                ImageButton btnMore = root.findViewById(R.id.btnMore);
                if (btnMore != null) {
                    btnMore.setColorFilter(ContextCompat.getColor(requireContext(), R.color.text_white));
                }
            }
            Toast.makeText(requireContext(), R.string.reminder_time_in_past_cleared, Toast.LENGTH_SHORT).show();
        }

        final long finalReminderTimeValue = reminderTimeValue;

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            Toast.makeText(requireContext(), R.string.auth_error_login_required, Toast.LENGTH_SHORT).show();
            return;
        }

        if (isEditMode) {
            if (editingTaskId == null || editingTaskId.trim().isEmpty()) {
                Toast.makeText(requireContext(), R.string.delete_task_failed, Toast.LENGTH_SHORT).show();
                return;
            }

            java.util.Map<String, Object> updates = new java.util.HashMap<>();
            updates.put("title", title);
            updates.put("description", description);
            updates.put("priority", selectedPriority);
            updates.put("dueDate", dueDateValue);
            updates.put("categoryId", categoryId);
            updates.put("reminderTime", finalReminderTimeValue);

            tasksRef.document(editingTaskId.trim())
                    .update(updates)
                    .addOnSuccessListener(unused -> {
                        Task temp = new Task();
                        temp.setId(editingTaskId.trim());
                        temp.setTitle(title);
                        temp.setReminderTime(finalReminderTimeValue);
                        if (finalReminderTimeValue > System.currentTimeMillis()) {
                            ReminderManager.ensureNotificationPermission(requireActivity());
                        }
                        ReminderManager.setReminder(requireContext(), temp);

                        Toast.makeText(requireContext(), R.string.edit_task_success, Toast.LENGTH_SHORT).show();
                        dismiss();
                    })
                    .addOnFailureListener(e -> Toast.makeText(requireContext(), e.getMessage(), Toast.LENGTH_SHORT).show());
            return;
        }

        addNewTaskWithNextOrder(tasksRef, title, description, dueDateValue, finalReminderTimeValue);
    }

    private void addNewTaskWithNextOrder(@NonNull CollectionReference tasksRef,
                                        @NonNull String title,
                                        @NonNull String description,
                                        @NonNull Long dueDateValue,
                                        long reminderTimeValue) {
        // Use a time-based order to avoid Firestore composite-index requirements.
        // (Drag & drop will later rewrite orders to 1..N anyway.)
        int nextOrder = (int) (System.currentTimeMillis() / 1000L);
        Task task = new Task(title, description, categoryId, selectedPriority, dueDateValue, reminderTimeValue, nextOrder);
        task.setCompleted(false);
        task.setOrder(nextOrder);
        task.setCreatedAt(null);

        tasksRef
                .add(task)
                .addOnSuccessListener(documentReference -> {
                    documentReference.update("createdAt", FieldValue.serverTimestamp());

                    // Schedule reminder after we have a stable Firestore doc id.
                    task.setId(documentReference.getId());
                    if (reminderTimeValue > System.currentTimeMillis()) {
                        ReminderManager.ensureNotificationPermission(requireActivity());
                    }
                    ReminderManager.setReminder(requireContext(), task);

                    Toast.makeText(requireContext(), R.string.add_task_success, Toast.LENGTH_SHORT).show();
                    dismiss();
                })
                .addOnFailureListener(e -> Toast.makeText(requireContext(), e.getMessage(), Toast.LENGTH_SHORT).show());
    }

    private void showReminderTimePicker() {
        restoreTaskInputFocus();

        // Use dueDate as the reminder date to avoid selecting the date twice.
        long baseDate = selectedDueDate > 0
                ? selectedDueDate
                : getStartOfTodayMillis();

        final java.util.Calendar base = java.util.Calendar.getInstance();
        base.setTimeInMillis(baseDate);

        int initialHour;
        int initialMinute;
        if (selectedReminderTime > 0) {
            java.util.Calendar existing = java.util.Calendar.getInstance();
            existing.setTimeInMillis(selectedReminderTime);
            initialHour = existing.get(java.util.Calendar.HOUR_OF_DAY);
            initialMinute = existing.get(java.util.Calendar.MINUTE);
        } else {
            // Default to the next hour to reduce chances of picking a past time.
            java.util.Calendar now = java.util.Calendar.getInstance();
            initialHour = now.get(java.util.Calendar.HOUR_OF_DAY);
            initialMinute = now.get(java.util.Calendar.MINUTE);
        }

        android.app.TimePickerDialog timePickerDialog = new android.app.TimePickerDialog(
                requireContext(),
                (timeView, hourOfDay, minute) -> {
                    java.util.Calendar picked = java.util.Calendar.getInstance();
                    picked.setTimeInMillis(baseDate);
                    picked.set(java.util.Calendar.HOUR_OF_DAY, hourOfDay);
                    picked.set(java.util.Calendar.MINUTE, minute);
                    picked.set(java.util.Calendar.SECOND, 0);
                    picked.set(java.util.Calendar.MILLISECOND, 0);

                    selectedReminderTime = picked.getTimeInMillis();

                    View root = getView();
                    if (root != null) {
                        ImageButton btnMore = root.findViewById(R.id.btnMore);
                        if (btnMore != null) {
                            btnMore.setColorFilter(android.graphics.Color.parseColor("#FF9800"));
                        }
                    }
                },
                initialHour,
                initialMinute,
                true
        );
        timePickerDialog.show();
    }

    private void updateSendMicVisibility(@Nullable ImageButton btnMicrophone,
                                        @Nullable ImageButton btnSend,
                                        @Nullable CharSequence text) {
        boolean hasText = text != null && !text.toString().trim().isEmpty();
        if (btnMicrophone != null) {
            btnMicrophone.setVisibility(hasText ? View.GONE : View.VISIBLE);
        }
        if (btnSend != null) {
            btnSend.setVisibility(hasText ? View.VISIBLE : View.GONE);
        }
    }

    private String extractTitle(String rawInput) {
        String[] lines = rawInput.split("\\n", 2);
        String firstLine = lines[0].trim();
        return firstLine.isEmpty() ? rawInput : firstLine;
    }

    private String extractDescription(String rawInput) {
        String[] lines = rawInput.split("\\n", 2);
        if (lines.length < 2) {
            return "";
        }
        return lines[1].trim();
    }

    private long normalizeToStartOfDay(long millis) {
        if (millis <= 0) {
            return 0L;
        }
        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.setTimeInMillis(millis);
        calendar.set(java.util.Calendar.HOUR_OF_DAY, 0);
        calendar.set(java.util.Calendar.MINUTE, 0);
        calendar.set(java.util.Calendar.SECOND, 0);
        calendar.set(java.util.Calendar.MILLISECOND, 0);
        return calendar.getTimeInMillis();
    }

    private long getStartOfTodayMillis() {
        return normalizeToStartOfDay(System.currentTimeMillis());
    }

    private static class PriorityOption {
        final int value;
        final String title;
        final String tintHex;

        PriorityOption(int value, String title, String tintHex) {
            this.value = value;
            this.title = title;
            this.tintHex = tintHex;
        }

        @NonNull
        @Override
        public String toString() {
            return title;
        }
    }
}

package com.example.ticktok.fragment;

import android.graphics.Rect;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.GridLayoutManager;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.ticktok.R;
import com.example.ticktok.adapter.CalendarAdapter;
import com.example.ticktok.adapter.EisenhowerTaskAdapter;
import com.example.ticktok.adapter.TaskAdapter;
import com.example.ticktok.model.Task;
import com.example.ticktok.util.UserFirestorePaths;
import com.google.firebase.firestore.CollectionReference;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.ListenerRegistration;
import com.google.firebase.firestore.QueryDocumentSnapshot;
import com.google.firebase.firestore.QuerySnapshot;

import java.util.ArrayList;
import java.util.Calendar;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class CalendarFragment extends Fragment {

    private static final long MILLIS_PER_DAY = 24L * 60L * 60L * 1000L;

    private RecyclerView rvCalendar;
    private CalendarAdapter calendarAdapter;
    private RecyclerView rvTasks;
    private TaskAdapter taskAdapter;
    private View layoutEmptyState;
    private TextView tvTabCalendar;
    private TextView tvTabEisenhower;
    private View layoutCalendarContent;
    private View layoutEisenhowerContent;

    private RecyclerView rvQuadrant1;
    private RecyclerView rvQuadrant2;
    private RecyclerView rvQuadrant3;
    private RecyclerView rvQuadrant4;
    private TextView tvEmptyQuadrant1;
    private TextView tvEmptyQuadrant2;
    private TextView tvEmptyQuadrant3;
    private TextView tvEmptyQuadrant4;
    private EisenhowerTaskAdapter quadrantAdapter1;
    private EisenhowerTaskAdapter quadrantAdapter2;
    private EisenhowerTaskAdapter quadrantAdapter3;
    private EisenhowerTaskAdapter quadrantAdapter4;

    private final Calendar displayedMonth = Calendar.getInstance();
    private int leadingEmptyDays;
    private long selectedDateMillis = 0L;
    private ListenerRegistration taskListener;
    private ListenerRegistration monthTaskMarkerListener;
    private ListenerRegistration eisenhowerListener;

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_calendar, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);
        tvTabCalendar = view.findViewById(R.id.tvTabCalendar);
        tvTabEisenhower = view.findViewById(R.id.tvTabEisenhower);
        layoutCalendarContent = view.findViewById(R.id.layoutCalendarContent);
        layoutEisenhowerContent = view.findViewById(R.id.layoutEisenhowerContent);
        layoutEmptyState = view.findViewById(R.id.layoutEmptyState);

        setupTabToggle();
        setupTaskList(view);
        setupCalendar(view);
        setupEisenhowerViews(view);
    }

    @Override
    public void onStart() {
        super.onStart();
        startTaskListener();
        startMonthTaskMarkerListener();
        startEisenhowerListener();
    }

    @Override
    public void onStop() {
        super.onStop();
        stopTaskListener();
        stopMonthTaskMarkerListener();
        stopEisenhowerListener();
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        stopTaskListener();
        stopMonthTaskMarkerListener();
        stopEisenhowerListener();
        rvCalendar = null;
        rvTasks = null;
        calendarAdapter = null;
        taskAdapter = null;
        layoutEmptyState = null;
        tvTabCalendar = null;
        tvTabEisenhower = null;
        layoutCalendarContent = null;
        layoutEisenhowerContent = null;

        rvQuadrant1 = null;
        rvQuadrant2 = null;
        rvQuadrant3 = null;
        rvQuadrant4 = null;
        tvEmptyQuadrant1 = null;
        tvEmptyQuadrant2 = null;
        tvEmptyQuadrant3 = null;
        tvEmptyQuadrant4 = null;
        quadrantAdapter1 = null;
        quadrantAdapter2 = null;
        quadrantAdapter3 = null;
        quadrantAdapter4 = null;
    }

    public Long getSelectedDateMillisForTask() {
        return selectedDateMillis > 0 ? selectedDateMillis : null;
    }

    private void setupTaskList(@NonNull View rootView) {
        rvTasks = rootView.findViewById(R.id.rvTasks);
        if (rvTasks == null) {
            return;
        }
        rvTasks.setLayoutManager(new LinearLayoutManager(requireContext()));
        if (rvTasks.getItemDecorationCount() == 0) {
            rvTasks.addItemDecoration(new VerticalSpaceItemDecoration(dpToPx(2)));
        }
        taskAdapter = new TaskAdapter(null, null, this::onTaskCheckedChanged);
        rvTasks.setAdapter(taskAdapter);
    }

    private void onTaskCheckedChanged(@NonNull Task task, boolean isChecked) {
        if (!isAdded()) {
            return;
        }
        if (task.getId() == null || task.getId().trim().isEmpty()) {
            return;
        }

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            return;
        }

        tasksRef.document(task.getId().trim())
                .update(
                        // Write both keys to be compatible with Firestore POJO mapping.
                        "isCompleted", isChecked,
                        "completed", isChecked,
                        "completedAt", isChecked ? FieldValue.serverTimestamp() : null
                );
    }

    private void setupCalendar(@NonNull View rootView) {
        rvCalendar = rootView.findViewById(R.id.rvCalendar);
        if (rvCalendar == null) {
            return;
        }

        if (rvCalendar.getLayoutManager() == null) {
            rvCalendar.setLayoutManager(new GridLayoutManager(requireContext(), 7));
        }

        List<String> monthDays = daysInMonthList();
        calendarAdapter = new CalendarAdapter(monthDays, this::onCalendarDaySelected);
        rvCalendar.setAdapter(calendarAdapter);

        int todayPosition = findTodayPosition(monthDays);
        if (todayPosition != RecyclerView.NO_POSITION) {
            calendarAdapter.setSelectedPosition(todayPosition);
            onCalendarDaySelected(todayPosition, monthDays.get(todayPosition));
        } else {
            showEmptyState(true);
        }

        startMonthTaskMarkerListener();
    }

    private void setupEisenhowerViews(@NonNull View rootView) {
        rvQuadrant1 = rootView.findViewById(R.id.rvQuadrant1);
        rvQuadrant2 = rootView.findViewById(R.id.rvQuadrant2);
        rvQuadrant3 = rootView.findViewById(R.id.rvQuadrant3);
        rvQuadrant4 = rootView.findViewById(R.id.rvQuadrant4);

        tvEmptyQuadrant1 = rootView.findViewById(R.id.tvEmptyQuadrant1);
        tvEmptyQuadrant2 = rootView.findViewById(R.id.tvEmptyQuadrant2);
        tvEmptyQuadrant3 = rootView.findViewById(R.id.tvEmptyQuadrant3);
        tvEmptyQuadrant4 = rootView.findViewById(R.id.tvEmptyQuadrant4);

        quadrantAdapter1 = new EisenhowerTaskAdapter(this::onTaskCheckedChanged);
        quadrantAdapter2 = new EisenhowerTaskAdapter(this::onTaskCheckedChanged);
        quadrantAdapter3 = new EisenhowerTaskAdapter(this::onTaskCheckedChanged);
        quadrantAdapter4 = new EisenhowerTaskAdapter(this::onTaskCheckedChanged);

        bindQuadrantRecycler(rvQuadrant1, quadrantAdapter1);
        bindQuadrantRecycler(rvQuadrant2, quadrantAdapter2);
        bindQuadrantRecycler(rvQuadrant3, quadrantAdapter3);
        bindQuadrantRecycler(rvQuadrant4, quadrantAdapter4);

        showQuadrantEmpty(tvEmptyQuadrant1, true);
        showQuadrantEmpty(tvEmptyQuadrant2, true);
        showQuadrantEmpty(tvEmptyQuadrant3, true);
        showQuadrantEmpty(tvEmptyQuadrant4, true);
    }

    private void bindQuadrantRecycler(@Nullable RecyclerView recyclerView, @Nullable EisenhowerTaskAdapter adapter) {
        if (recyclerView == null || adapter == null) {
            return;
        }
        recyclerView.setLayoutManager(new LinearLayoutManager(requireContext()));
        recyclerView.setAdapter(adapter);
    }

    private void onCalendarDaySelected(int position, @NonNull String dayValue) {
        if (dayValue.trim().isEmpty()) {
            return;
        }

        int dayOfMonth;
        try {
            dayOfMonth = Integer.parseInt(dayValue);
        } catch (NumberFormatException ignored) {
            return;
        }

        Calendar selectedDay = (Calendar) displayedMonth.clone();
        selectedDay.set(Calendar.DAY_OF_MONTH, 1);
        selectedDay.add(Calendar.DAY_OF_MONTH, position - leadingEmptyDays);
        selectedDay.set(Calendar.DAY_OF_MONTH, dayOfMonth);
        selectedDay.set(Calendar.HOUR_OF_DAY, 0);
        selectedDay.set(Calendar.MINUTE, 0);
        selectedDay.set(Calendar.SECOND, 0);
        selectedDay.set(Calendar.MILLISECOND, 0);

        selectedDateMillis = selectedDay.getTimeInMillis();
        startTaskListener();
    }

    private void startTaskListener() {
        if (!isAdded() || taskAdapter == null) {
            return;
        }
        if (selectedDateMillis <= 0) {
            taskAdapter.submitList(new ArrayList<>());
            showEmptyState(true);
            return;
        }

        stopTaskListener();
        long dayStart = selectedDateMillis;
        long dayEnd = dayStart + MILLIS_PER_DAY;

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            taskAdapter.submitList(new ArrayList<>());
            showEmptyState(true);
            return;
        }

        taskListener = tasksRef
                .whereGreaterThanOrEqualTo("dueDate", dayStart)
                .whereLessThan("dueDate", dayEnd)
                .addSnapshotListener((snapshot, error) -> {
                    if (!isAdded() || taskAdapter == null) {
                        return;
                    }
                    if (error != null || snapshot == null) {
                        showEmptyState(true);
                        return;
                    }

                    List<Task> tasks = mapSnapshotToTasks(snapshot);
                    taskAdapter.submitList(tasks);
                    showEmptyState(tasks.isEmpty());
                });
    }

    private void stopTaskListener() {
        if (taskListener != null) {
            taskListener.remove();
            taskListener = null;
        }
    }

    private void startMonthTaskMarkerListener() {
        if (!isAdded() || calendarAdapter == null) {
            return;
        }

        stopMonthTaskMarkerListener();

        Calendar monthStartCalendar = (Calendar) displayedMonth.clone();
        monthStartCalendar.set(Calendar.DAY_OF_MONTH, 1);
        monthStartCalendar.set(Calendar.HOUR_OF_DAY, 0);
        monthStartCalendar.set(Calendar.MINUTE, 0);
        monthStartCalendar.set(Calendar.SECOND, 0);
        monthStartCalendar.set(Calendar.MILLISECOND, 0);

        long monthStart = monthStartCalendar.getTimeInMillis();

        Calendar nextMonthStartCalendar = (Calendar) monthStartCalendar.clone();
        nextMonthStartCalendar.add(Calendar.MONTH, 1);
        long nextMonthStart = nextMonthStartCalendar.getTimeInMillis();

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            calendarAdapter.setDayPositionsWithTasks(new HashSet<>());
            return;
        }

        monthTaskMarkerListener = tasksRef
                .whereGreaterThanOrEqualTo("dueDate", monthStart)
                .whereLessThan("dueDate", nextMonthStart)
                .addSnapshotListener((snapshot, error) -> {
                    if (!isAdded() || calendarAdapter == null) {
                        return;
                    }
                    if (error != null || snapshot == null) {
                        calendarAdapter.setDayPositionsWithTasks(new HashSet<>());
                        return;
                    }

                    Set<Integer> markedPositions = mapSnapshotToMarkedDayPositions(snapshot);
                    calendarAdapter.setDayPositionsWithTasks(markedPositions);
                });
    }

    private void stopMonthTaskMarkerListener() {
        if (monthTaskMarkerListener != null) {
            monthTaskMarkerListener.remove();
            monthTaskMarkerListener = null;
        }
    }

    private void startEisenhowerListener() {
        if (!isAdded() || quadrantAdapter1 == null || quadrantAdapter2 == null
                || quadrantAdapter3 == null || quadrantAdapter4 == null) {
            return;
        }

        CollectionReference tasksRef = UserFirestorePaths.getUserCollection("tasks");
        if (tasksRef == null) {
            submitQuadrantLists(new ArrayList<>(), new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
            return;
        }

        stopEisenhowerListener();
        eisenhowerListener = tasksRef
                .addSnapshotListener((snapshot, error) -> {
                    if (!isAdded() || quadrantAdapter1 == null || quadrantAdapter2 == null
                            || quadrantAdapter3 == null || quadrantAdapter4 == null) {
                        return;
                    }
                    if (error != null || snapshot == null) {
                        submitQuadrantLists(new ArrayList<>(), new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
                        return;
                    }

                    List<Task> allTasks = mapSnapshotToTasks(snapshot);
                    partitionAndRenderEisenhower(allTasks);
                });
    }

    private void stopEisenhowerListener() {
        if (eisenhowerListener != null) {
            eisenhowerListener.remove();
            eisenhowerListener = null;
        }
    }

    private void partitionAndRenderEisenhower(@NonNull List<Task> tasks) {
        List<Task> q1 = new ArrayList<>();
        List<Task> q2 = new ArrayList<>();
        List<Task> q3 = new ArrayList<>();
        List<Task> q4 = new ArrayList<>();

        for (Task task : tasks) {
            if (task == null || task.isCompleted()) {
                continue;
            }

            switch (task.getPriority()) {
                case 3:
                    // Priority 3 -> Quadrant I
                    q1.add(task);
                    break;
                case 2:
                    // Priority 2 -> Quadrant II
                    q2.add(task);
                    break;
                case 1:
                    // Priority 1 -> Quadrant III
                    q3.add(task);
                    break;
                case 0:
                default:
                    // Priority 0 (or invalid) -> Quadrant IV
                    q4.add(task);
                    break;
            }
        }

        submitQuadrantLists(q1, q2, q3, q4);
    }

    private void submitQuadrantLists(@NonNull List<Task> q1,
                                     @NonNull List<Task> q2,
                                     @NonNull List<Task> q3,
                                     @NonNull List<Task> q4) {
        quadrantAdapter1.submitList(q1);
        quadrantAdapter2.submitList(q2);
        quadrantAdapter3.submitList(q3);
        quadrantAdapter4.submitList(q4);

        showQuadrantEmpty(tvEmptyQuadrant1, q1.isEmpty());
        showQuadrantEmpty(tvEmptyQuadrant2, q2.isEmpty());
        showQuadrantEmpty(tvEmptyQuadrant3, q3.isEmpty());
        showQuadrantEmpty(tvEmptyQuadrant4, q4.isEmpty());
    }

    private void showQuadrantEmpty(@Nullable TextView view, boolean show) {
        if (view != null) {
            view.setVisibility(show ? View.VISIBLE : View.GONE);
        }
    }

    @NonNull
    private Set<Integer> mapSnapshotToMarkedDayPositions(@NonNull QuerySnapshot snapshot) {
        Set<Integer> markedPositions = new HashSet<>();
        int displayedYear = displayedMonth.get(Calendar.YEAR);
        int displayedMonthValue = displayedMonth.get(Calendar.MONTH);

        for (QueryDocumentSnapshot doc : snapshot) {
            Task task = doc.toObject(Task.class);
            Long dueDate = task.getDueDate();
            if (dueDate == null) {
                continue;
            }

            Calendar dueCalendar = Calendar.getInstance();
            dueCalendar.setTimeInMillis(dueDate);
            if (dueCalendar.get(Calendar.YEAR) != displayedYear
                    || dueCalendar.get(Calendar.MONTH) != displayedMonthValue) {
                continue;
            }

            int dayOfMonth = dueCalendar.get(Calendar.DAY_OF_MONTH);
            int position = leadingEmptyDays + dayOfMonth - 1;
            if (position >= 0 && position < 42) {
                markedPositions.add(position);
            }
        }

        return markedPositions;
    }

    @NonNull
    private List<Task> mapSnapshotToTasks(@NonNull QuerySnapshot snapshot) {
        List<Task> tasks = new ArrayList<>();
        for (QueryDocumentSnapshot doc : snapshot) {
            Task task = doc.toObject(Task.class);
            task.setId(doc.getId());
            tasks.add(task);
        }
        return tasks;
    }

    private void showEmptyState(boolean show) {
        if (layoutEmptyState != null) {
            layoutEmptyState.setVisibility(show ? View.VISIBLE : View.GONE);
        }
        if (rvTasks != null) {
            rvTasks.setVisibility(show ? View.GONE : View.VISIBLE);
        }
    }

    private void setupTabToggle() {
        if (tvTabCalendar == null || tvTabEisenhower == null
                || layoutCalendarContent == null || layoutEisenhowerContent == null) {
            return;
        }

        tvTabCalendar.setOnClickListener(v -> switchTab(true));
        tvTabEisenhower.setOnClickListener(v -> switchTab(false));

        switchTab(true);
    }

    private void switchTab(boolean showCalendarTab) {
        if (tvTabCalendar == null || tvTabEisenhower == null
                || layoutCalendarContent == null || layoutEisenhowerContent == null) {
            return;
        }

        layoutCalendarContent.setVisibility(showCalendarTab ? View.VISIBLE : View.GONE);
        layoutEisenhowerContent.setVisibility(showCalendarTab ? View.GONE : View.VISIBLE);

        if (showCalendarTab) {
            tvTabCalendar.setBackgroundResource(R.drawable.bg_calendar_tab_selected);
            tvTabCalendar.setTextColor(requireContext().getColor(R.color.text_white));
            tvTabEisenhower.setBackground(null);
            tvTabEisenhower.setTextColor(0xCCFFFFFF);
        } else {
            tvTabEisenhower.setBackgroundResource(R.drawable.bg_calendar_tab_selected);
            tvTabEisenhower.setTextColor(requireContext().getColor(R.color.text_white));
            tvTabCalendar.setBackground(null);
            tvTabCalendar.setTextColor(0xCCFFFFFF);
        }
    }

    @NonNull
    private List<String> daysInMonthList() {
        List<String> days = new ArrayList<>();

        displayedMonth.setTimeInMillis(System.currentTimeMillis());
        displayedMonth.set(Calendar.DAY_OF_MONTH, 1);

        int maxDaysOfMonth = displayedMonth.getActualMaximum(Calendar.DAY_OF_MONTH);
        int firstDayOfWeek = displayedMonth.get(Calendar.DAY_OF_WEEK);

        leadingEmptyDays = firstDayOfWeek - Calendar.SUNDAY;
        for (int i = 0; i < leadingEmptyDays; i++) {
            days.add("");
        }

        for (int day = 1; day <= maxDaysOfMonth; day++) {
            days.add(String.valueOf(day));
        }

        while (days.size() < 42) {
            days.add("");
        }

        return days;
    }

    private int findTodayPosition(@NonNull List<String> monthDays) {
        String today = String.valueOf(Calendar.getInstance().get(Calendar.DAY_OF_MONTH));
        for (int i = 0; i < monthDays.size(); i++) {
            if (today.equals(monthDays.get(i))) {
                return i;
            }
        }
        return RecyclerView.NO_POSITION;
    }

    private int dpToPx(int dp) {
        return Math.round(dp * requireContext().getResources().getDisplayMetrics().density);
    }

    private static class VerticalSpaceItemDecoration extends RecyclerView.ItemDecoration {
        private final int verticalSpacePx;

        VerticalSpaceItemDecoration(int verticalSpacePx) {
            this.verticalSpacePx = verticalSpacePx;
        }

        @Override
        public void getItemOffsets(@NonNull Rect outRect,
                                   @NonNull View view,
                                   @NonNull RecyclerView parent,
                                   @NonNull RecyclerView.State state) {
            int position = parent.getChildAdapterPosition(view);
            if (position == RecyclerView.NO_POSITION) {
                return;
            }
            outRect.top = position == 0 ? 0 : verticalSpacePx;
        }
    }
}

package com.example.ticktok.fragment;

import android.graphics.Rect;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.GridLayoutManager;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.ticktok.R;
import com.example.ticktok.adapter.CalendarAdapter;
import com.example.ticktok.adapter.EisenhowerTaskAdapter;
import com.example.ticktok.adapter.TaskAdapter;
import com.example.ticktok.model.Task;
import com.example.ticktok.reminder.ReminderManager;
import com.example.ticktok.util.UserFirestorePaths;
import com.google.firebase.firestore.CollectionReference;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.ListenerRegistration;
import com.google.firebase.firestore.QueryDocumentSnapshot;
import com.google.firebase.firestore.QuerySnapshot;

import java.util.ArrayList;
import java.util.Calendar;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class CalendarFragment extends Fragment {

    private static final long MILLIS_PER_DAY = 24L * 60L * 60L * 1000L;

    private RecyclerView rvCalendar;
    private CalendarAdapter calendarAdapter;
    private RecyclerView rvTasks;
    private TaskAdapter taskAdapter;
    private View layoutEmptyState;
    private TextView tvTabCalendar;
    private TextView tvTabEisenhower;
    private View layoutCalendarContent;
    private View layoutEisenhowerContent;

    private RecyclerView rvQuadrant1;
    private RecyclerView rvQuadrant2;
    private RecyclerView rvQuadrant3;
    private RecyclerView rvQuadrant4;
    private TextView tvEmptyQuadrant1;
    private TextView tvEmptyQuadrant2;
    private TextView tvEmptyQuadrant3;
    private TextView tvEmptyQuadrant4;
    private EisenhowerTaskAdapter quadrantAdapter1;
    private EisenhowerTaskAdapter quadrantAdapter2;
    private EisenhowerTaskAdapter quadrantAdapter3;
    private EisenhowerTaskAdapter quadrantAdapter4;

    private final Calendar displayedMonth = Calendar.getInstance();
    private int leadingEmptyDays;
    private long selectedDateMillis = 0L;
    private ListenerRegistration taskListener;
    private ListenerRegistration monthTaskMarkerListener;
    private ListenerRegistration eisenhowerListener;

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_calendar, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);
        tvTabCalendar = view.findViewById(R.id.tvTabCalendar);
        tvTabEisenhower = view.findViewById(R.id.tvTabEisenhower);
